#!/usr/bin/env python3
"""Build one Home Assistant package from the source-controlled script files."""

from __future__ import annotations

import argparse
from pathlib import Path

import yaml


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("scripts_dir", type=Path)
    parser.add_argument("output", type=Path)
    args = parser.parse_args()

    script_files = sorted(args.scripts_dir.glob("*.yaml"))
    if not script_files:
        raise SystemExit(f"no scripts found in {args.scripts_dir}")

    sections = [
        "# Generated by tools/build_script_package.py; do not edit on Home Assistant.\n",
        "script:\n",
    ]
    seen_ids: set[str] = set()

    for path in script_files:
        script_id = path.stem.replace("-", "_")
        if script_id in seen_ids:
            raise SystemExit(f"duplicate generated script ID: {script_id}")
        seen_ids.add(script_id)

        source = path.read_text(encoding="utf-8")
        parsed = yaml.safe_load(source)
        if not isinstance(parsed, dict):
            raise SystemExit(f"{path} must contain one script mapping")

        sections.append(f"  {script_id}:\n")
        for line in source.rstrip().splitlines():
            sections.append(f"    {line}\n" if line else "\n")

    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text("".join(sections), encoding="utf-8")


if __name__ == "__main__":
    main()
